-- ============================================================
-- BloodNet v2 (bnetv2_db) — DEMO/TEST USER DATA (INSERT)
-- 200 demo users (130 donors / 70 requesters)
-- All names suffixed ' (Demo Account)'. User-facing data only —
-- no admin accounts, no new locations, no settings changes.
--
-- Reserved ID ranges (safe against live max ids checked 2026-08-19:
-- users<=8, donations<=15, calls<=17, activity_log<=285):
--   users:         100001 .. 100200
--   donations:     200001 .. 200287
--   calls:         300001 .. 300260
--   activity_log:  400001 .. 400150
--   seek_exclusions: no surrogate id — requester_id/donor_id
--     both fall in 100001..100200
--
-- Uses only existing location ids (1, 2, 3) — no new locations.
--
-- NOTE: password_hash values are placeholder strings, not real
-- bcrypt hashes. They will NOT work for login. Ask if you need
-- working demo credentials.
--
-- No BEGIN TRANSACTION/COMMIT: D1 manages atomicity itself and
-- rejects raw SQL transaction statements. Statements are chunked
-- to <=20 rows each to stay under D1's per-statement size limit.
-- ============================================================

PRAGMA foreign_keys = ON;

